"""Persist explicit generated bytes; never interpret a Markdown path as read authority."""

from __future__ import annotations

import base64
import binascii
import hashlib
import json
import logging
import mimetypes
import re
from io import BytesIO
from typing import Any

from omnigent.db.db_models import current_workspace_id, normalize_uuid
from omnigent.entities.conversation import MessageData, NativeToolData, NewConversationItem

logger = logging.getLogger(__name__)
_MAX_OUTPUT_BYTES = 50 * 1024 * 1024
_MIME_TYPE = re.compile(r"[\w!#$%&'*+.^`|~-]+/[\w!#$%&'*+.^`|~-]+(?:;[^\r\n,]+)?", re.ASCII)


class _AttachmentError(ValueError):
    """An attachment failure safe to display without exposing storage details."""


def _decode_base64(payload: str) -> bytes:
    if len(payload) > 4 * ((_MAX_OUTPUT_BYTES + 2) // 3):
        raise _AttachmentError("Generated attachment exceeds 50 MB")
    try:
        content = base64.b64decode(payload, validate=True)
    except (ValueError, binascii.Error) as exc:
        raise _AttachmentError("Generated attachment contains invalid base64 data") from exc
    if len(content) > _MAX_OUTPUT_BYTES:
        raise _AttachmentError("Generated attachment exceeds 50 MB")
    return content


def _decode_uri(uri: str) -> tuple[bytes, str]:
    header, separator, payload = uri.partition(",")
    if not separator or not header.endswith(";base64"):
        raise _AttachmentError("Generated attachment requires a base64 data URI")
    mime = header[5:-7]
    if (
        len(mime) > 256
        or not _MIME_TYPE.fullmatch(mime)
        or any(not 32 <= ord(char) < 127 for char in mime)
    ):
        raise _AttachmentError("Generated attachment has an invalid MIME type")
    return _decode_base64(payload), mime


def _native_image(payload: str) -> tuple[bytes, str, str]:
    from PIL import Image

    content = _decode_base64(payload)
    try:
        with Image.open(BytesIO(content), formats=["PNG", "JPEG", "WEBP"]) as image:
            assert image.format is not None
            mime = Image.MIME[image.format]
    except (OSError, ValueError) as exc:
        raise _AttachmentError("Generated image has invalid or unsupported image data") from exc
    extension = ".jpg" if mime == "image/jpeg" else f".{mime.split('/')[1]}"
    return content, mime, f"generated-image{extension}"


def persist_generated_outputs(
    session_id: str, items: list[NewConversationItem]
) -> list[NewConversationItem]:
    """Replace generated bytes with session-owned files, isolating each attachment's errors.

    Inline failures become output text; native failures use an ``error`` on their
    client-only attachment card, which replay must strip with the other metadata.
    """
    from omnigent.runtime import get_artifact_store, get_file_store

    files, artifacts = get_file_store(), get_artifact_store()

    def store(content: bytes, mime: str, filename: str) -> dict[str, Any]:
        if files is None or artifacts is None:
            raise _AttachmentError("Attachment storage is unavailable")
        if not filename or len(filename) > 512 or any(ord(char) < 32 for char in filename):
            raise _AttachmentError("Generated attachment has an invalid filename")
        owner = normalize_uuid(session_id)
        scope = json.dumps([current_workspace_id(), owner, mime, filename]).encode()
        file_id = hashlib.sha256(scope + b"\0" + content).hexdigest()[:32]
        record = files.get(file_id, session_id=owner)
        if record is None or not artifacts.exists(record.blob_key or record.id):
            # Publish metadata only after bytes exist; concurrent retries write identical bytes.
            artifacts.put(
                (record.blob_key or record.id) if record is not None else file_id, content
            )
            if record is None:
                try:
                    record = files.create(
                        filename=filename,
                        bytes=len(content),
                        content_type=mime,
                        session_id=owner,
                        file_id=file_id,
                        source_metadata={"original": True, "delivery": "display"},
                    )
                except Exception:
                    # A concurrent idempotent append may have published the same file first.
                    record = files.get(file_id, session_id=owner)
                    if record is None:
                        raise
        return {"type": "output_file", "file_id": record.id, "filename": record.filename}

    def failure(exc: Exception) -> str:
        if isinstance(exc, _AttachmentError):
            return f"Attachment error: {exc}."
        logger.error(
            "Could not persist generated attachment for session %s", session_id, exc_info=exc
        )
        return "Attachment error: Generated attachment could not be saved. Try again."

    result = []
    for item in items:
        if isinstance(item.data, MessageData) and item.data.role == "assistant":
            content = []
            for block in item.data.content:
                uri = block.get("image_url") or block.get("file_data")
                if (
                    block.get("type")
                    in {"output_image", "input_image", "input_file", "output_file"}
                    and ("image_url" in block or "file_data" in block)
                    and (not isinstance(uri, str) or uri.startswith("data:") or not uri)
                ):
                    try:
                        if not isinstance(uri, str):
                            raise _AttachmentError(
                                "Generated attachment requires a base64 data URI"
                            )
                        decoded, mime = _decode_uri(uri)
                        stem = "generated-image" if mime.startswith("image/") else "generated-file"
                        filename = block.get("filename")
                        if filename is None or filename == "":
                            filename = stem + (
                                mimetypes.guess_extension(mime.split(";")[0]) or ".bin"
                            )
                        if not isinstance(filename, str):
                            raise _AttachmentError("Generated attachment has an invalid filename")
                        content.append(store(decoded, mime, filename))
                    except Exception as exc:
                        content.append({"type": "output_text", "text": failure(exc)})
                else:
                    content.append(block)
            item = item.model_copy(
                update={"data": item.data.model_copy(update={"content": content})}
            )
        elif isinstance(item.data, NativeToolData):
            native = item.data.item
            if native.get("type") == "image_generation_call" and (
                "result" in native
                or (native.get("status") == "completed" and "omnigent_attachments" not in native)
            ):
                payload = native.get("result")
                if payload is None and native.get("status") != "completed":
                    result.append(item)
                    continue
                try:
                    if not isinstance(payload, str) or not payload:
                        raise _AttachmentError("Generated image contains no image data")
                    attached = store(*_native_image(payload))
                except Exception as exc:
                    attached = {
                        "type": "output_file",
                        "filename": "generated-image",
                        "error": failure(exc),
                    }
                    # Invalid or oversized bytes must not survive as a second rendering path.
                    native = {key: value for key, value in native.items() if key != "result"}
                item = item.model_copy(
                    update={
                        "data": NativeToolData(item={**native, "omnigent_attachments": [attached]})
                    }
                )
        result.append(item)
    return result
